          height: 48.0,
          fit: BoxFit.cover,
          errorBuilder: (context, error, stackTrace) {
            // 本地图片加载失败时，使用默认图标
            return _buildLocalIcon();
          },
        ),
      );
    } else if (iconUrl != null && iconUrl.isNotEmpty) {
      // 如果是 assets 路径，使用本地图标
      if (iconUrl.startsWith('assets/')) {
        iconWidget = ClipRRect(
          borderRadius: BorderRadius.circular(8.0),
          child: Image.asset(
            iconUrl,
            width: 48.0,
            height: 48.0,
            fit: BoxFit.cover,
            errorBuilder: (context, error, stackTrace) {
              // 本地图片加载失败时，使用默认图标
              return _buildLocalIcon();
            },
          ),
        );
      } else {
        // 使用网络图片
        iconWidget = ClipRRect(
          borderRadius: BorderRadius.circular(8.0),
          child: Image.network(
            iconUrl,
            width: 48.0,
            height: 48.0,
            fit: BoxFit.cover,
            errorBuilder: (context, error, stackTrace) {
              // 网络图片加载失败时，使用本地图标
              return _buildLocalIcon();
            },
            loadingBuilder: (context, child, loadingProgress) {
              if (loadingProgress == null) {
                return child;
